Given a tuple of string/number/symbol values, produce an object type whose keys and values are those tuple elements.

**Requirements:**
- Declare and export `TupleToObject<T>` where `T` is a readonly tuple of keys.
- The result is `{ [P in T[number]]: P }`.

**Example:**
```ts
type A = TupleToObject<['tesla', 'model 3']>;
// => { tesla: 'tesla'; 'model 3': 'model 3' }
```

files.content:
// Type-level assertion helpers for ts-types-drills.
// Adapted from type-challenges (https://github.com/type-challenges/type-challenges) — MIT.

export type Expect<T extends true> = T;

export type Equal<X, Y> = (<T>() => T extends X ? 1 : 2) extends <T>() => T extends Y ? 1 : 2
  ? true
  : false;

export type NotEqual<X, Y> = Equal<X, Y> extends true ? false : true;

export type NotAny<T> = [T] extends [never] ? false : 0 extends 1 & T ? false : true;

import type { Expect, Equal } from './type-utils.js';

export type TupleToObject<T extends readonly (string | number | symbol)[]> = {
  [P in T[number]]: P;
};

type cases = [
  Expect<Equal<TupleToObject<['tesla', 'model 3']>, { tesla: 'tesla'; 'model 3': 'model 3' }>>,
  Expect<Equal<TupleToObject<[1, 2, 3]>, { 1: 1; 2: 2; 3: 3 }>>,
];

export type { cases };
